import { CONFIG, createSheepComposition } from './config.js';

const typeNames = ['green', 'yellow', 'orange', 'red', 'lightBlue', 'blue'];
const decodeRect = (rect, kind) => ({ x: rect[0], y: rect[1], width: rect[2], height: rect[3], ...(kind ? { kind } : {}) });
const decodeCircle = (circle, kind) => ({ x: circle[0], y: circle[1], radius: circle[2], kind });
const decodeLine = (line, label) => ({ x: line[0], y: line[1], width: line[2], height: line[3], label: label || 'GATE' });
export function L(data) {
  const counts = data.s || [];
  const obstacleKind = (value) => {
    if (value === 1) return 'rock';
    if (value === 2) return 'water';
    if (value === 3) return 'bush';
    if (value === 4) return 'building';
    return 'fence';
  };
  return {
    title: data.t || 'CUSTOM FIELD',
    name: data.d || 'Custom level',
    timeLimit: data.m || 600,
    world: data.w ? { width: data.w[0], height: data.w[1] } : CONFIG.world,
    playerStart: data.p ? { x: data.p[0], y: data.p[1] } : undefined,
    flockStarts: (data.f || []).map((point) => point.length > 2 ? { x: point[0], y: point[1], sheepCounts: Object.fromEntries(typeNames.map((type, index) => [type, point[2 + index] || 0])) } : { x: point[0], y: point[1] }),
    target: data.z ? decodeRect(data.z) : { x: -10000, y: -10000, width: 1, height: 1 },
    sheepCounts: Object.fromEntries(typeNames.map((type, index) => [type, counts[index] || 0])),
    obstacles: (data.o || []).map((shape) => {
      const code = shape[4];
      if (shape.length >= 5 && shape[3] === 0 && (code === 2 || code === 3)) return decodeCircle(shape, obstacleKind(code));
      return decodeRect(shape, obstacleKind(code));
    }),
    gates: (data.g || []).map((gate) => decodeLine(gate, gate[4]))
  };
}

