export const LEVEL_SETTINGS = {
  default: PRACTICE_FIELD,
  preview: {
    title: 'FIELD SELECT',
    name: 'A quiet field before the work begins.',
    timeLimit: 0,
    world: CONFIG.world,
    flockStart: { x: 1800, y: 1100 },
    target: { x: -10000, y: -10000, width: 1, height: 1 },
    sheepCounts: { green: 120, yellow: 20, orange: 10, red: 4, lightBlue: 6, blue: 3 },
    obstacles: [],
    gates: []
  }
};

export function getLevelSettings() {
  return { ...LEVEL_SETTINGS, ...CUSTOM_LEVELS };
}

export function registerLevel(levelId, settings) {
  CUSTOM_LEVELS[levelId] = settings;
}

export function unregisterLevel(levelId) {
  delete CUSTOM_LEVELS[levelId];
}

export function buildLevel(levelId = 'default') {
  const settings = getLevelSettings()[levelId] || LEVEL_SETTINGS.default;
  return {
    ...settings,
    composition: createSheepComposition(settings.sheepCounts),
    obstacles: (settings.obstacles || []).map((obstacle) => ({ ...obstacle })),
    gates: (settings.gates || []).map((gate) => ({ ...gate }))
  };
}
